    };
}
function d_finish_note(array $p): string {
    $v = (string)$p['variant']; $n = (string)$p['card_name'];
    if (str_contains($n, 'Master Ball Pattern') || str_contains($v, 'Master Ball')) return 'Finish: Master Ball pattern reverse holo, the scarcer of the two pattern printings.';
    if (str_contains($n, 'Poke Ball Pattern') || str_contains($v, 'Poke Ball')) return 'Finish: PokÃ© Ball pattern reverse holo, with PokÃ© Balls worked into the foil.';
    if (preg_match('/Love Ball|Friend Ball|Quick Ball/', $v, $m)) return "Finish: reverse holo with a {$m[0]} pattern.";
    if (str_contains($n, 'Cosmos Holofoil')) return 'Finish: cosmos holofoil, the starry foil pattern used on many promos.';
    if (str_starts_with($v, 'Reverse Holofoil')) return 'Finish: reverse holo, with the foil on the frame around the artwork instead of on the artwork itself.';
    if ($v === 'Holofoil' && in_array($p['rarity'], ['Common', 'Uncommon', 'Rare'], true)) return 'Finish: holo foil.';
    return '';
}
function d_secret_note(array $p): string {
    if (preg_match('#^(\d+)/(\d+)$#', (string)$p['card_number'], $m) && (int)$m[1] > (int)$m[2] && $p['rarity'] !== 'Secret Rare')
        return "Look at the number: {$p['card_number']} goes beyond the {$m[2]} cards in the setâ€™s official count, which makes it a secret rare.";
    return '';
}
function d_clean_name(array $p): string {
    $n = trim((string)$p['card_name']);
    $n = trim(preg_replace('/\s*\((Master Ball|Poke Ball) Pattern\)/', '', $n));
    return $n !== '' ? $n : (string)$p['title'];
}
function d_set_link(array $p): string {
    if (empty($p['set_url']) || empty($p['set_name'])) return '';
    return '<a href="' . h($p['set_url']) . '">' . h($p['set_name']) . '</a>';
}
function d_card_page(array $p): string {
    foreach (auto_paths($p) as $path) if (preg_match('#^/cards/(' . implode('|', CARD_NAMES) . ')-pokemon-cards$#', $path, $m))
        return '<a href="' . $path . '">' . ucfirst($m[1]) . ' cards</a>';
    return '';
}
// The priciest singles we carry from the same set (read from the catalog, so it stays accurate).
function d_chase(array $p, int $n = 3): array {
    static $cache = [];
    if (empty($p['set_url'])) return [];
    if (!isset($cache[$p['set_url']])) {
        $cache[$p['set_url']] = all("SELECT id, handle, card_name, title, card_number FROM products WHERE set_url = ? AND section = 'Single Cards' AND published = 1 AND price_usd IS NOT NULL ORDER BY price_usd DESC LIMIT 12", [$p['set_url']]);
    }
    $out = []; $seen = [];
    foreach ($cache[$p['set_url']] as $r) {
        if ((int)$r['id'] === (int)($p['id'] ?? 0)) continue;
        $nm = trim(preg_replace(['/\s*\((Master Ball|Poke Ball) Pattern\)/', '#^\d+\*?/\d+\s+#'], '', $r['card_name'] ?: $r['title']));
        if (isset($seen[$nm]) || $nm === d_clean_name($p)) continue;
        $seen[$nm] = 1;
        $out[] = '<a href="/products/' . h($r['handle']) . '">' . h($nm . ($r['card_number'] ? ' ' . $r['card_number'] : '')) . '</a>';
        if (count($out) >= $n) break;
    }
    return $out;
}
function d_ship(array $p, bool $sealed = false): string {
    return d_pick($p, [
        'Delivery: ships from our warehouse in Japan within two days of payment, tracked by EMS, DHL or FedEx, and usually reaches the US in 3 to 6 working days.',
        'Delivery: sent from Japan within two days of payment with EMS, DHL or FedEx tracking. Standard shipping is free on orders over $2,000.',
        'Delivery: priced in US dollars and dispatched from Japan within two days of your payment clearing, fully tracked by EMS, DHL or FedEx.',
        'Delivery: tracked door to door from Japan by EMS, DHL or FedEx, leaving within two days of payment.',
    ], 11);
}
function d_lang_note(array $p): string {
    $lang = $p['language'] ?? 'English';
    if ($lang === 'Japanese') return d_pick($p, [
        'Language: Japanese. Japanese cards are the standard 63 x 88 mm, the same as English, so your sleeves, toploaders and binder pages all fit.',
        'Language: Japanese. It shares the 63 x 88 mm size of English cards, and many graders like the Japanese print finish.',
        'Language: Japanese. Japanese sets usually come out months before the English version, at the same card size.',
    ], 9);
    if ($lang === 'Chinese') return 'Language: Simplified Chinese, an official printing for the PokÃ©mon TCGâ€™s Chinese market and a growing collecting niche.';
    return d_pick($p, ['Language: English, the edition sold in US stores.', 'Language: English, standard 63 x 88 mm size.'], 9);
}

/* ------------------------------------------------------------------ singles */
function d_pokemon_single(array $p): array {
    $name = d_clean_name($p); $num = (string)$p['card_number']; $rar = (string)$p['rarity']; $type = (string)$p['card_type'];
    $setName = (string)$p['set_name']; $series = (string)$p['series'];
    $kind = preg_match('/\bEnergy\b/', $name) ? 'Energy card' : (is_trainer_card($p) ? 'Trainer card' : ($type !== '' ? "$type-type PokÃ©mon" : 'PokÃ©mon card'));
    if ($p['subsection'] === 'Jumbo cards') $kind = 'jumbo card';
    $lang = d_lang($p);
    $setTxt = $setName !== '' ? d_set_link($p) . ($series !== '' && !str_contains($setName, $series) ? ", part of the $series series" : '') : '';
    $id = '<strong>' . h($name) . '</strong>' . ($num !== '' ? " ($num)" : '');
    $rarTxt = $rar !== '' ? "$rar " : '';
    $s1 = $setTxt !== ''
        ? d_pick($p, [
            "Searching for $id? This $rarTxt$kind is from " . ($lang === 'English' ? '' : "the $lang version of ") . "$setTxt.",
            "$id is " . d_an($rarTxt ?: $kind) . " $rarTxt$kind in " . ($lang === 'English' ? '' : "the $lang printing of ") . "$setTxt.",
            "From " . ($lang === 'English' ? '' : "$lang ") . "$setTxt: $id, " . d_an($rarTxt ?: $kind) . " $rarTxt$kind.",
        ], 21)
        : "$id is " . d_an($rarTxt ?: $kind) . " $rarTxt$kind from " . ($lang !== 'English' ? "a $lang printing." : 'a special release.');
    if ($p['subsection'] === 'Jumbo cards') $s1 = "$id is a jumbo-size card, the oversized display card included in premium collection boxes. It is too big for play.";
    $para1 = trim($s1 . ' ' . d_finish_note($p) . ' ' . d_secret_note($p));
    $para2 = d_rarity_note($p);
    $chase = d_chase($p);
    $setLine = '';
    if ($chase) $setLine = d_pick($p, [
            'Also from this set: ' . d_list($chase) . '. See the <a href="' . h($p['set_url']) . '">full ' . h($setName) . ' checklist</a> for every card we stock and its price.',
            'More standout cards from ' . h($setName) . ' in stock: ' . d_list($chase) . '. The <a href="' . h($p['set_url']) . '">' . h($setName) . ' checklist</a> has the rest.',
        ], 23);
    $cp = d_card_page($p);
    if ($cp) $setLine .= ($setLine ? ' ' : '') . "Want another version? Our $cp page gathers every printing we carry.";
    $para3 = 'Condition: one raw, ungraded card. ' . d_lang_note($p) . ' ' . d_ship($p);
    return array_filter([$para1, $para2, $setLine, $para3]);
}
