function not_found(): never {
    http_response_code(404);
    echo view('layout', ['meta' => ['title' => 'Page not found | ' . setting('site_name'), 'robots' => 'noindex'], 'content' => view('notfound')]);
    exit;
}

function store_route(string $path): void {
    if ($path === '/index.php') redirect('/', 301);

    // admin-managed redirects
    if ($r = one('SELECT * FROM redirects WHERE from_path = ?', [$path])) {
        q('UPDATE redirects SET hits = hits + 1 WHERE from_path = ?', [$path]);
        redirect($r['to_path'], (int)$r['code']);
    }

    switch (true) {
        case $path === '/': page_home(); return;
        case (bool)preg_match('#^/img/([a-z0-9-]+)\.jpg$#', $path, $m): serve_product_image($m[1]);
        case $path === '/robots.txt': page_robots(); return;
        case $path === '/feed/google.xml': page_google_feed(); return;
        case $path === '/sitemap.xml': page_sitemap_index(); return;
        case (bool)preg_match('#^/sitemap-(pages|products)-(\d+)\.xml$#', $path, $m): page_sitemap($m[1], (int)$m[2]); return;
        case $path === '/api/cart': api_cart(); return;
        case $path === '/api/search': api_search(); return;
        case $path === '/api/quick': api_quick(); return;
        case (bool)preg_match('#^/currency/([A-Z]{3})$#', $path, $m): set_currency($m[1]); return;
        case $path === '/cart': page_cart(); return;
        case $path === '/checkout': page_checkout(); return;
        case (bool)preg_match('#^/order/([A-Z0-9-]+)$#', $path, $m): page_order($m[1]); return;
        case $path === '/quick-order': page_quick(); return;
        case $path === '/search': page_listing(null, trim((string)($_GET['q'] ?? ''))); return;
        case $path === '/sets': page_sets(); return;
        case $path === '/reviews': page_reviews(); return;
        case $path === '/guides': page_index('guide'); return;
        case $path === '/blog': page_index('blog'); return;
        case (bool)preg_match('#^/products/([a-z0-9-]+)$#', $path, $m): page_product($m[1]); return;
    }
    if ($c = one('SELECT * FROM collections WHERE path = ?', [$path])) { page_listing($c); return; }
    if ($pg = one('SELECT * FROM pages WHERE path = ? AND published = 1', [$path])) { page_content($pg); return; }
    not_found();
}

function set_currency(string $cur): void {
    if (isset(rates()[$cur])) setcookie('cur', $cur, ['expires' => time() + 31536000, 'path' => '/', 'samesite' => 'Lax']);
    $back = $_GET['back'] ?? '/';
    redirect(str_starts_with($back, '/') && !str_starts_with($back, '//') ? $back : '/');
}

/* ------------------------------------------------------------------ home */
function page_home(): void {
    $featured = all("SELECT * FROM products WHERE published = 1 AND in_stock = 1 AND price_usd IS NOT NULL AND section IN ('Booster Boxes','Elite Trainer Boxes','Premium & Special Sets','Booster Box Cases')
                     ORDER BY featured DESC, (language = 'Japanese') DESC, price_usd DESC LIMIT 10");
    $singles = all("SELECT * FROM products WHERE published = 1 AND in_stock = 1 AND section = 'Single Cards' AND seo_index = 1 ORDER BY featured DESC, price_usd DESC LIMIT 10");
    $cats = all("SELECT c.path, c.title, c.h1, (SELECT COUNT(*) FROM product_paths pp JOIN products p ON p.id = pp.product_id AND p.published = 1 WHERE pp.path = c.path) n
                 FROM collections c WHERE c.kind = 'section' ORDER BY c.sort_order");
    $games = all("SELECT c.path, c.title, (SELECT COUNT(*) FROM product_paths pp WHERE pp.path = c.path) n FROM collections c WHERE c.kind = 'game' AND c.path != '/pokemon' ORDER BY n DESC LIMIT 12");
    // newest sets first (the date we first listed product from them), only sets with a real page
    $sets = all("SELECT c.path, c.title, c.series, COUNT(pp.product_id) n, MIN(p.created_at) first_seen FROM collections c JOIN product_paths pp ON pp.path = c.path JOIN products p ON p.id = pp.product_id AND p.published = 1
                 WHERE c.kind = 'set' AND c.game = 'PokÃ©mon' AND c.seo_index = 1 GROUP BY c.path HAVING n >= 20 ORDER BY first_seen DESC, n DESC LIMIT 12");
    // the hero: the featured set (Admin â€º Settings), its sealed product and its chase cards
    $heroSet = one('SELECT path, title, h1, series FROM collections WHERE path = ?', [setting('hero_set') ?: '/sets/30th-celebration']);
    $show = ['set' => $heroSet, 'main' => null, 'side' => [], 'chase' => []];
    if ($heroSet) {
        $img = "(p.image_url != '' OR p.image_local NOT IN ('', '!'))";
        $sealed = all("SELECT p.* FROM products p JOIN product_paths pp ON pp.product_id = p.id AND pp.path = ? WHERE p.published = 1 AND p.price_usd IS NOT NULL AND $img
                       AND p.section IN ('Booster Boxes','Elite Trainer Boxes','Premium & Special Sets','Booster Box Cases','Booster Packs')
                       ORDER BY p.in_stock DESC, CASE p.section WHEN 'Booster Boxes' THEN 1 WHEN 'Elite Trainer Boxes' THEN 2 WHEN 'Premium & Special Sets' THEN 3 ELSE 4 END, (p.language = 'Japanese') DESC, p.price_usd DESC LIMIT 6", [$heroSet['path']]);
        $show['main'] = $sealed[0] ?? null;
        foreach (array_slice($sealed, 1) as $x) if (count($show['side']) < 2 && $x['section'] !== 'Booster Box Cases' && $x['section'] !== ($show['main']['section'] ?? '')) $show['side'][] = $x;
        $show['chase'] = all("SELECT p.* FROM products p JOIN product_paths pp ON pp.product_id = p.id AND pp.path = ? WHERE p.published = 1 AND p.section = 'Single Cards' AND p.price_usd IS NOT NULL AND $img
                              ORDER BY p.price_usd DESC LIMIT 4", [$heroSet['path']]);
    }
    // fallback hero: three chase cards in stock, with a photo
    $chase = all("SELECT * FROM products WHERE published = 1 AND in_stock = 1 AND section = 'Single Cards' AND game = 'PokÃ©mon' AND price_usd IS NOT NULL
                  AND (image_url != '' OR image_local NOT IN ('', '!')) ORDER BY featured DESC, price_usd DESC LIMIT 3");
    $pokemon = [];
    foreach (CARD_NAMES as $n) { $cnt = (int)val('SELECT COUNT(*) FROM product_paths WHERE path = ?', ["/cards/$n-pokemon-cards"]); if ($cnt) $pokemon[] = [ucfirst($n), "/cards/$n-pokemon-cards", $cnt]; }
    usort($pokemon, fn($a, $b) => $b[2] <=> $a[2]);
    $guides = all("SELECT * FROM pages WHERE type IN ('guide','blog') AND published = 1 ORDER BY updated_at DESC LIMIT 3");
    $stats = ['products' => (int)val('SELECT COUNT(*) FROM products WHERE published = 1'), 'instock' => (int)val('SELECT COUNT(*) FROM products WHERE published = 1 AND in_stock = 1')];
    $meta = ['title' => 'Toramori: Japanese & English PokÃ©mon Cards from Japan',
             'description' => 'Toramori ships PokÃ©mon cards from Japan: booster boxes, Elite Trainer Boxes, singles and PSA slabs in Japanese and English, priced in US dollars, tracked.',
             'canonical' => '/', 'schema' => [org_schema(), ['@context' => 'https://schema.org', '@type' => 'WebSite', 'name' => setting('site_name'), 'url' => setting('site_url'),
               'potentialAction' => ['@type' => 'SearchAction', 'target' => setting('site_url') . '/search?q={q}', 'query-input' => 'required name=q']]]];
    $reviews = reviews_list(null, true, 6);
    echo view('layout', ['meta' => $meta, 'content' => view('home', compact('featured', 'singles', 'cats', 'games', 'sets', 'guides', 'stats', 'reviews', 'chase', 'pokemon', 'show'))]);
}
function org_schema(): array {
    return ['@context' => 'https://schema.org', '@type' => 'Organization', 'name' => setting('site_name'), 'alternateName' => setting('site_name_ja'),
            'url' => setting('site_url'), 'logo' => setting('site_url') . '/assets/img/logo-512.png', 'email' => setting('support_email'),
            'contactPoint' => ['@type' => 'ContactPoint', 'contactType' => 'customer support', 'email' => setting('support_email'), 'url' => setting('site_url') . '/contact'],
            'hasMerchantReturnPolicy' => return_policy_schema()];
}
// The returns rules on /returns-refunds, for Google: 7 days, by mail to Japan, return shipping paid by the buyer unless the fault was ours.
function return_policy_schema(): array {
    return ['@type' => 'MerchantReturnPolicy', 'applicableCountry' => 'US', 'returnPolicyCountry' => 'JP',
            'returnPolicyCategory' => 'https://schema.org/MerchantReturnFiniteReturnWindow', 'merchantReturnDays' => 7,
            'returnMethod' => 'https://schema.org/ReturnByMail', 'returnFees' => 'https://schema.org/ReturnFeesCustomerResponsibility',
            'merchantReturnLink' => setting('site_url') . '/returns-refunds'];
}
// Who makes it: the game for trading cards, the maker for sports cards and accessories, nothing when it isn't clear.
function product_brand(array $p): ?string {
    if (preg_match('/\b(Panini|Topps|Upper Deck|Leaf|Bowman|Donruss|Futera|Ultra Pro|Dragon Shield|Ultimate Guard|BCW|Card Saver)\b/i', $p['title'], $m)) return $m[1];
    if (in_array($p['game'], ['Sports', 'Accessories', 'Other collectibles', 'Collectibles', 'Anime promos'], true)) return preg_match('/Pok[eÃ©]mon/i', $p['title']) ? 'PokÃ©mon' : null;
    return $p['game'] ?: null;
}

/* ------------------------------------------------------------------ listings with filters & sorting */
const SORTS = ['best' => 'Best match', 'number' => 'Set & card number', 'price_asc' => 'Price: low to high', 'price_desc' => 'Price: high to low', 'newest' => 'Newest', 'name' => 'Name Aâ€“Z'];
const SECTION_ORDER = "CASE p.section WHEN 'Booster Box Cases' THEN 1 WHEN 'Cases' THEN 1 WHEN 'Booster Boxes' THEN 2 WHEN 'Booster & Hobby Boxes' THEN 2 WHEN 'Elite Trainer Boxes' THEN 3 WHEN 'Premium & Special Sets' THEN 4 WHEN 'Decks, Bundles & Sets' THEN 4 WHEN 'Booster Packs' THEN 5 WHEN 'Packs' THEN 5 WHEN 'PSA Graded Cards' THEN 6 WHEN 'Graded Cards' THEN 6 WHEN 'Single Cards' THEN 7 ELSE 8 END";

function listing_query(?array $c, string $search, array $f, ?string $skip = null): array {
    $where = ['p.published = 1']; $args = [];
    $join = '';
    if ($c) { $join = 'JOIN product_paths pp ON pp.product_id = p.id AND pp.path = ?'; $args[] = $c['path']; }
    if ($search !== '') {
        foreach (preg_split('/\s+/', mb_strtolower($search)) as $w) {
            if ($w === '') continue;
            $where[] = "(LOWER(p.title) LIKE ? OR LOWER(p.sku) LIKE ? OR LOWER(p.set_name) LIKE ?)";
            array_push($args, "%$w%", "%$w%", "%$w%");
        }
    }
    foreach (['game' => 'p.game', 'section' => 'p.section', 'set' => 'p.set_name', 'lang' => 'p.language', 'rarity' => 'p.rarity'] as $k => $col) {
        if ($k === $skip || empty($f[$k])) continue;
        $vals = (array)$f[$k];
        $where[] = "$col IN (" . implode(',', array_fill(0, count($vals), '?')) . ')';
        array_push($args, ...$vals);
    }
    if ($skip !== 'stock' && !empty($f['stock'])) $where[] = 'p.in_stock = 1';
    $rate = rates()[currency()] ?? 1;
    if (is_numeric($f['min'] ?? null)) { $where[] = 'p.price_usd >= ?'; $args[] = (float)$f['min'] / $rate; }
    if (is_numeric($f['max'] ?? null)) { $where[] = 'p.price_usd <= ?'; $args[] = (float)$f['max'] / $rate; }
    return ["FROM products p $join WHERE " . implode(' AND ', $where), $args];
}

function page_listing(?array $c, string $search = ''): void {
    $f = [];
    foreach (['game', 'section', 'set', 'lang', 'rarity'] as $k) if (isset($_GET[$k]) && $_GET[$k] !== '') $f[$k] = array_slice(array_map('strval', (array)$_GET[$k]), 0, 20);
    $f['stock'] = !empty($_GET['stock']);
    $f['min'] = $_GET['min'] ?? ''; $f['max'] = $_GET['max'] ?? '';
    $defaultSort = ($c && $c['kind'] === 'set') ? 'number' : 'best';
    $sort = isset(SORTS[$_GET['sort'] ?? '']) ? $_GET['sort'] : $defaultSort;
    $per = in_array((int)($_GET['per'] ?? 0), [24, 48, 96], true) ? (int)$_GET['per'] : 48;
    $view = in_array($_GET['view'] ?? ($_COOKIE['view'] ?? ''), ['grid', 'list'], true) ? ($_GET['view'] ?? $_COOKIE['view']) : 'grid';
    if (isset($_GET['view'])) setcookie('view', $view, ['expires' => time() + 31536000, 'path' => '/', 'samesite' => 'Lax']);
    $page = max(1, (int)($_GET['page'] ?? 1));

    [$from, $args] = listing_query($c, $search, $f);
    $total = (int)val("SELECT COUNT(*) $from", $args);
    $order = match ($sort) {
        'number' => 'p.in_stock DESC, p.set_name, ' . SECTION_ORDER . ', p.sort_number IS NULL, p.sort_number, p.card_number, p.title',
        'price_asc' => 'p.price_usd IS NULL, p.price_usd ASC',
        'price_desc' => 'p.price_usd IS NULL, p.price_usd DESC',
        'newest' => 'p.created_at DESC, p.id DESC',
        'name' => 'p.title COLLATE NOCASE',
        default => 'p.in_stock DESC, p.featured DESC, ' . SECTION_ORDER . ', p.seo_index DESC, p.price_usd DESC',
    };
    $pages = max(1, (int)ceil($total / $per));
    $page = min($page, $pages);
    $items = all("SELECT p.* $from ORDER BY $order LIMIT $per OFFSET " . (($page - 1) * $per), $args);

    // facets: each one counts with every other filter applied
    $facets = [];
    foreach (['game' => 'p.game', 'section' => 'p.section', 'lang' => 'p.language', 'set' => 'p.set_name', 'rarity' => 'p.rarity'] as $k => $col) {
        [$ff, $fa] = listing_query($c, $search, $f, $k);
        $rows = all("SELECT $col v, COUNT(*) n $ff AND $col != '' GROUP BY $col ORDER BY " . ($k === 'set' || $k === 'rarity' ? 'n DESC' : 'n DESC') . ' LIMIT 40', $fa);
        if (count($rows) > 1 || !empty($f[$k])) $facets[$k] = $rows;
    }
    [$sf, $sa] = listing_query($c, $search, $f, 'stock');
    $instock = (int)val("SELECT COUNT(*) $sf AND p.in_stock = 1", $sa);

    $hasFilters = $search !== '' || array_filter([$f['game'] ?? null, $f['section'] ?? null, $f['set'] ?? null, $f['lang'] ?? null, $f['rarity'] ?? null, $f['stock'] ?: null, $f['min'] !== '' ? 1 : null, $f['max'] !== '' ? 1 : null]);
    $base = $c ? $c['path'] : '/search';
    if ($c) {
        $title = $c['seo_title'] ?: $c['title'] . ' | ' . setting('site_name');
        $meta = ['title' => $title . ($page > 1 ? " â€“ page $page" : ''), 'description' => $c['meta_desc'],
                 'canonical' => $c['path'] . ($page > 1 ? "?page=$page" : ''),
                 'robots' => ($hasFilters || isset($_GET['sort']) || isset($_GET['per']) || isset($_GET['view']) || !$c['seo_index'] || $total === 0) ? 'noindex,follow' : 'index,follow',
                 'schema' => [breadcrumb_schema(listing_crumbs($c)), item_list_schema($items)]];
    } else {
        $meta = ['title' => ($search !== '' ? "Search: $search" : 'Search') . ' | ' . setting('site_name'), 'robots' => 'noindex,follow', 'canonical' => '/search'];
    }
    $crumbs = $c ? listing_crumbs($c) : [['Home', '/'], ['Search', '']];
    // set pages carry the full card list (what "<set> card list" searches want), on the clean first page only
    $cardlist = ($c && $c['kind'] === 'set' && $page === 1 && !$hasFilters) ? all("SELECT p.id, p.handle, p.card_name, p.title, p.card_number, p.rarity, p.variant, p.price_usd, p.in_stock, p.language FROM products p JOIN product_paths pp ON pp.product_id = p.id AND pp.path = ?
        WHERE p.published = 1 AND p.section = 'Single Cards' ORDER BY p.sort_number IS NULL, p.sort_number, p.card_number, p.card_name", [$c['path']]) : [];
    if (count($cardlist) < 10) $cardlist = [];
    echo view('layout', ['meta' => $meta, 'content' => view('listing', compact('c', 'search', 'f', 'sort', 'per', 'view', 'page', 'pages', 'total', 'items', 'facets', 'instock', 'base', 'crumbs', 'cardlist') + ['links' => $c ? collection_related($c) : []])]);
}
function listing_crumbs(array $c): array {
    $cr = [['Home', '/']];
    if ($c['kind'] === 'set') { $cr[] = ['Sets', '/sets']; if ($c['game'] && $c['game'] !== 'PokÃ©mon') { $g = one("SELECT path, title FROM collections WHERE kind='game' AND game = ?", [$c['game']]); if ($g) $cr[] = [$g['title'], $g['path']]; } }
    elseif ($c['kind'] === 'game_section') { $g = one("SELECT path, title FROM collections WHERE kind='game' AND game = ?", [$c['game']]); if ($g) $cr[] = [$g['title'], $g['path']]; }
    elseif ($c['kind'] !== 'shop') $cr[] = ['Shop', '/shop'];
    $cr[] = [$c['h1'] ?: $c['title'], $c['path']];
    return $cr;
}
function breadcrumb_schema(array $crumbs): array {
    $items = [];
    foreach ($crumbs as $i => [$name, $url]) $items[] = ['@type' => 'ListItem', 'position' => $i + 1, 'name' => $name] + ($url ? ['item' => setting('site_url') . $url] : []);
    return ['@context' => 'https://schema.org', '@type' => 'BreadcrumbList', 'itemListElement' => $items];
}
function item_list_schema(array $items): array {
    $list = [];
    foreach (array_slice($items, 0, 24) as $i => $p) $list[] = ['@type' => 'ListItem', 'position' => $i + 1, 'url' => setting('site_url') . '/products/' . $p['handle']];
    return ['@context' => 'https://schema.org', '@type' => 'ItemList', 'itemListElement' => $list];
}
function listing_url(string $base, array $params, array $change = []): string {
    $q = array_merge($params, $change);
    foreach ($q as $k => $v) if ($v === null || $v === '' || $v === [] || $v === false) unset($q[$k]);
    if (($q['page'] ?? 1) == 1) unset($q['page']);
    return $base . ($q ? '?' . http_build_query($q) : '');
}

/* ------------------------------------------------------------------ sets hub, guides index */
function page_sets(): void {
    $sets = all("SELECT c.path, c.title, c.h1, c.game, c.series, COUNT(pp.product_id) n,
                   SUM(CASE WHEN p.in_stock = 1 THEN 1 ELSE 0 END) instock, MIN(p.created_at) first_seen
                 FROM collections c LEFT JOIN product_paths pp ON pp.path = c.path LEFT JOIN products p ON p.id = pp.product_id AND p.published = 1
                 WHERE c.kind = 'set' GROUP BY c.path ORDER BY c.game != 'PokÃ©mon', c.game, c.series, first_seen DESC, c.title");
    $meta = ['title' => 'PokÃ©mon Sets List: Every Card Set | ' . setting('site_name'),
             'description' => 'The full list of PokÃ©mon sets, newest at the top, plus Riftbound, Lorcana and more, each with a numbered checklist and its sealed product.', 'canonical' => '/sets'];
    $c0 = one("SELECT * FROM collections WHERE path = '/sets'");
    if ($c0) $meta = ['title' => $c0['seo_title'], 'description' => $c0['meta_desc'], 'canonical' => '/sets'];
    $h1 = $c0['h1'] ?? 'All PokÃ©mon card sets';
    $intro = $c0['intro'] ?? '';
    echo view('layout', ['meta' => $meta, 'content' => view('sets', compact('sets', 'h1', 'intro'))]);
}
function page_index(string $type): void {
    $items = all('SELECT * FROM pages WHERE type = ? AND published = 1 ORDER BY published_at DESC', [$type]);
    $t = $type === 'guide' ? 'PokÃ©mon card guides for collectors' : 'News and stories';
    $meta = ['title' => $t . ' | ' . setting('site_name'), 'description' => $type === 'guide' ? 'Toramori guides for PokÃ©mon card collectors: card values, rarity symbols, grading, spotting fakes, card sizes and how to play the game.' : 'News from the PokÃ©mon card market by Toramori: record-breaking sales, new set releases and the cards collectors want now.', 'canonical' => '/' . ($type === 'guide' ? 'guides' : 'blog')];
    echo view('layout', ['meta' => $meta, 'content' => view('index', compact('items', 't', 'type'))]);
}
function page_content(array $pg): void {
    $pg['body'] = strtr($pg['body'], ['{support_email}' => h(setting('support_email')), '{btc_address}' => h(setting('btc_address'))]);
    $related = [];
    if (preg_match_all('#href="(/(?:sets|cards)/[a-z0-9-]+|/(?:booster-boxes|single-cards|elite-trainer-boxes|booster-packs))"#', $pg['body'], $m)) {
        $paths = array_slice(array_unique($m[1]), 0, 3);
        foreach ($paths as $path) foreach (all('SELECT p.* FROM products p JOIN product_paths pp ON pp.product_id = p.id AND pp.path = ? WHERE p.published = 1 AND p.in_stock = 1 ORDER BY p.price_usd DESC LIMIT 4', [$path]) as $r) $related[$r['id']] = $r;
    }
    if (!$related && $pg['type'] !== 'page') $related = all("SELECT * FROM products WHERE published = 1 AND in_stock = 1 AND section IN ('Booster Boxes','Elite Trainer Boxes') ORDER BY featured DESC, price_usd DESC LIMIT 4");
    $isArticle = in_array($pg['type'], ['guide', 'blog'], true);
    $crumbs = [['Home', '/']];
    if ($pg['type'] === 'guide') $crumbs[] = ['Guides', '/guides'];
    if ($pg['type'] === 'blog') $crumbs[] = ['Blog', '/blog'];
    $crumbs[] = [$pg['h1'] ?: $pg['title'], $pg['path']];
    $schema = [breadcrumb_schema($crumbs)];
    if ($isArticle) $schema[] = ['@context' => 'https://schema.org', '@type' => $pg['type'] === 'blog' ? 'BlogPosting' : 'Article', 'headline' => $pg['h1'] ?: $pg['title'],
        'datePublished' => substr($pg['published_at'], 0, 10), 'dateModified' => substr($pg['updated_at'], 0, 10), 'author' => ['@type' => 'Organization', 'name' => setting('site_name')],
        'publisher' => org_schema(), 'mainEntityOfPage' => setting('site_url') . $pg['path']];
    if (preg_match_all('#<h2>(.*?)</h2>\s*<p>(.*?)</p>#s', $pg['body'], $qa) && count($qa[1]) >= 2 && str_contains(strtolower($pg['body']), '?</h2>')) {
        $faq = [];
        foreach ($qa[1] as $i => $question) if (str_ends_with(trim(strip_tags($question)), '?')) $faq[] = ['@type' => 'Question', 'name' => strip_tags($question), 'acceptedAnswer' => ['@type' => 'Answer', 'text' => strip_tags($qa[2][$i])]];
        if (count($faq) >= 2) $schema[] = ['@context' => 'https://schema.org', '@type' => 'FAQPage', 'mainEntity' => $faq];
    }
    $meta = ['title' => $pg['seo_title'] ?: $pg['title'] . ' | ' . setting('site_name'), 'description' => $pg['meta_desc'], 'canonical' => $pg['path'],
             'robots' => $pg['seo_index'] ? 'index,follow' : 'noindex,follow', 'schema' => $schema, 'og_type' => $isArticle ? 'article' : 'website'];
    [$bodyHtml, $toc] = article_toc(sanitize_html($pg['body']));
    if (!$isArticle || count($toc) < 3) $toc = [];
    $topic = guide_topic_of($pg['path']);
    $more = [];
    if ($isArticle) {
        foreach ($topic ? GUIDE_TOPICS[$topic] : [] as $l) if ($l[1] !== $pg['path']) $more[] = $l;
        foreach (GUIDE_TOPICS as $t => $links) if ($t !== $topic && count($more) < 8) $more[] = $links[0];
    }
    echo view('layout', ['meta' => $meta, 'content' => view('page', compact('pg', 'related', 'crumbs', 'isArticle', 'bodyHtml', 'toc', 'more', 'topic'))]);
}

/* ------------------------------------------------------------------ internal links: guides grouped by topic, related pages */
const GUIDE_TOPICS = [
    'Value and prices' => [['What is my card worth?', '/guides/pokemon-card-values'], ['Checking card prices', '/guides/pokemon-card-price-checker'], ['Record-breaking sales', '/guides/most-expensive-pokemon-cards'], ['The rarest cards', '/guides/rarest-pokemon-cards'], ['Cards worth collecting', '/guides/coolest-pokemon-cards'], ['Best packs to buy', '/guides/best-pokemon-packs-to-buy']],
    'Know your cards' => [['Rarity symbols decoded', '/guides/pokemon-card-rarities'], ['Reading a card', '/guides/how-to-read-a-pokemon-card'], ['Is it fake?', '/guides/how-to-tell-if-a-pokemon-card-is-fake'], ['Getting cards graded', '/guides/how-to-grade-pokemon-cards'], ['What grading costs', '/guides/how-much-does-it-cost-to-grade-a-pokemon-card'], ['Sizes and sleeves', '/guides/pokemon-card-size']],
    'Sets and languages' => [['Japanese or English?', '/guides/japanese-pokemon-cards'], ['Vintage cards', '/guides/vintage-pokemon-cards'], ['Spotting 1st Edition', '/guides/first-edition-pokemon-cards'], ['Official Chinese cards', '/guides/chinese-pokemon-cards'], ['Card database', '/guides/pokemon-card-database'], ['Halloween cards', '/guides/halloween-pokemon-cards']],
    'Buying and selling' => [['Where to buy', '/guides/where-to-buy-pokemon-cards'], ['Where to sell', '/guides/where-to-sell-pokemon-cards'], ['Card shops near you', '/guides/pokemon-card-shops-near-me'], ['Card shows near you', '/guides/pokemon-card-shows-near-me'], ['Buying at Target', '/guides/pokemon-cards-at-target'], ['Buying at Walmart', '/guides/pokemon-cards-at-walmart']],
];
function guide_topic_of(string $path): ?string {
    foreach (GUIDE_TOPICS as $t => $links) foreach ($links as $l) if ($l[1] === $path) return $t;
    return null;
}
// guides that help with a product, by what kind of product it is
function guides_for_product(array $p): array {
    $k = product_kind($p);
    $g = match (true) {
        in_array($p['section'], ['PSA Graded Cards', 'Graded Cards'], true) => [['Getting cards graded', '/guides/how-to-grade-pokemon-cards'], ['What grading costs', '/guides/how-much-does-it-cost-to-grade-a-pokemon-card'], ['What is my card worth?', '/guides/pokemon-card-values']],
        $k === 'single' => [['What is my card worth?', '/guides/pokemon-card-values'], ['Rarity symbols decoded', '/guides/pokemon-card-rarities'], ['Is it fake?', '/guides/how-to-tell-if-a-pokemon-card-is-fake']],
        $k === 'sealed' => [['Best packs to buy', '/guides/best-pokemon-packs-to-buy'], ['Japanese or English?', '/guides/japanese-pokemon-cards'], ['Bulk buying terms', '/wholesale']],
        default => [['Sizes and sleeves', '/guides/pokemon-card-size'], ['Bulk buying terms', '/wholesale']],
    };
    if (($p['language'] ?? '') === 'Japanese' && $k !== 'sealed') $g[] = ['Japanese or English?', '/guides/japanese-pokemon-cards'];
    return $g;
}
// "Keep exploring" for a product page: other versions, its PokÃ©mon and card-type pages, its set, guides
function product_explore(array $p): array {
    $out = ['card' => [], 'set' => [], 'learn' => guides_for_product($p)];
    if ($p['set_url'] && $p['card_number'] !== '') {
        foreach (all("SELECT handle, title, card_name, variant FROM products WHERE set_url = ? AND card_number = ? AND id != ? AND published = 1 ORDER BY in_stock DESC LIMIT 4", [$p['set_url'], $p['card_number'], $p['id']]) as $r) {
            $v = preg_match('/\((Master Ball|Poke Ball) Pattern\)/', $r['card_name'], $m) ? $m[1] . ' pattern' : ($r['variant'] && $r['variant'] !== 'Normal' ? $r['variant'] : 'Regular');
            $out['card'][] = [$v . ' version', '/products/' . $r['handle']];
        }
    }
    $labels = ['ex' => 'PokÃ©mon ex cards', 'mega' => 'Mega cards', 'trainer' => 'Trainer cards', 'energy' => 'Energy cards', 'shiny' => 'Shiny cards', 'holo' => 'Holo cards', 'ultra-rare' => 'Ultra Rare cards', 'psa-10' => 'PSA 10 cards', 'psa-graded' => 'PSA graded cards', 'tag-team' => 'TAG TEAM cards', 'jumbo' => 'Jumbo cards'];
    foreach (array_merge(auto_paths($p), preg_split('/\s+/', trim((string)$p['also_on']))) as $path) {
        if (!preg_match('#^/cards/([a-z0-9-]+)-pokemon-cards$#', $path, $m)) continue;
        $label = $labels[$m[1]] ?? (in_array($m[1], CARD_NAMES, true) ? 'All ' . ucfirst($m[1]) . ' cards' : ucfirst(str_replace('-', ' ', $m[1])) . ' cards');
        $out['card'][] = [$label, $path];
    }
    if ($p['set_url'] && ($set = one('SELECT path, title, series FROM collections WHERE path = ?', [$p['set_url']]))) {
        $out['set'][] = [$set['title'] . ' checklist', $set['path'] . '#card-list'];
        $out['set'][] = ['All ' . $set['title'] . ' products', $set['path']];
        $series = ['Mega Evolution' => '/sets/mega-evolution', 'Scarlet & Violet' => '/sets/scarlet-violet', 'Sword & Shield' => '/sets/sword-shield'][$set['series']] ?? null;
        if ($series) $out['set'][] = ['All ' . $set['series'] . ' sets', $series];
    }
    if ($p['section_url'] && ($sec = one('SELECT path, title, h1 FROM collections WHERE path = ?', [$p['section_url']]))) $out['set'][] = [$sec['h1'] ?: $sec['title'], $sec['path']];
    $lang = ['Japanese' => '/japanese-pokemon-cards', 'English' => '/english-pokemon-cards', 'Chinese' => '/chinese-pokemon-cards'][$p['language']] ?? null;
    if ($p['game'] === 'PokÃ©mon' && $lang) $out['set'][] = [$p['language'] . ' PokÃ©mon cards', $lang];
    foreach ($out as $k => $v) { $seen = []; $out[$k] = array_values(array_filter($v, function ($l) use (&$seen) { if (isset($seen[$l[1]])) return false; return $seen[$l[1]] = true; })); }
    return $out;
}
// related pages shown under a listing page's heading
function collection_related(array $c): array {
    $r = [];
    $path = $c['path'];
    if ($c['kind'] === 'set') {
        $series = ['Mega Evolution' => '/sets/mega-evolution', 'Scarlet & Violet' => '/sets/scarlet-violet', 'Sword & Shield' => '/sets/sword-shield'][$c['series']] ?? null;
        if ($series) $r[] = ['All ' . $c['series'] . ' sets', $series];
        foreach (all("SELECT c.path, c.title, COUNT(pp.product_id) n FROM collections c JOIN product_paths pp ON pp.path = c.path WHERE c.kind = 'set' AND c.series = ? AND c.game = ? AND c.path != ? AND c.seo_index = 1 GROUP BY c.path ORDER BY n DESC LIMIT 5", [$c['series'], $c['game'], $path]) as $s) $r[] = [$s['title'], $s['path']];
        if ($c['game'] === 'PokÃ©mon') { $r[] = ['Every PokÃ©mon set', '/sets']; $r[] = ['Best packs to buy', '/guides/best-pokemon-packs-to-buy']; }
    } elseif (preg_match('#^/cards/([a-z0-9-]+)-pokemon-cards$#', $path, $m) && in_array($m[1], CARD_NAMES, true)) {
        foreach (CARD_NAMES as $n) if ($n !== $m[1] && count($r) < 7) $r[] = [ucfirst($n) . ' cards', "/cards/$n-pokemon-cards"];
        $r[] = ['PSA 10 cards', '/cards/psa-10-pokemon-cards']; $r[] = ['What are my cards worth?', '/guides/pokemon-card-values'];
    } elseif (str_starts_with($path, '/cards/')) {
        foreach ([['Full art', '/cards/full-art-pokemon-cards'], ['Gold', '/cards/gold-pokemon-cards'], ['PokÃ©mon ex', '/cards/ex-pokemon-cards'], ['Mega', '/cards/mega-pokemon-cards'], ['Shiny', '/cards/shiny-pokemon-cards'], ['Trainer', '/cards/trainer-pokemon-cards'], ['PSA 10', '/cards/psa-10-pokemon-cards'], ['PSA graded', '/cards/psa-graded-pokemon-cards']] as [$t, $u]) if ($u !== $path) $r[] = ["$t cards", $u];
        $r[] = ['Card rarities explained', '/guides/pokemon-card-rarities'];
    } else {
        $map = [
            '/booster-boxes' => [['Booster box cases', '/booster-box-cases'], ['Booster packs', '/booster-packs'], ['Elite Trainer Boxes', '/elite-trainer-boxes'], ['Japanese cards', '/japanese-pokemon-cards'], ['Best packs to buy', '/guides/best-pokemon-packs-to-buy'], ['Bulk and wholesale', '/wholesale']],
            '/booster-packs' => [['Booster boxes', '/booster-boxes'], ['Elite Trainer Boxes', '/elite-trainer-boxes'], ['Best packs to buy', '/guides/best-pokemon-packs-to-buy']],
            '/elite-trainer-boxes' => [['Booster boxes', '/booster-boxes'], ['Premium and special sets', '/premium-special-sets'], ['Booster box cases', '/booster-box-cases'], ['Best packs to buy', '/guides/best-pokemon-packs-to-buy']],
            '/single-cards' => [['Charizard cards', '/cards/charizard-pokemon-cards'], ['Pikachu cards', '/cards/pikachu-pokemon-cards'], ['Umbreon cards', '/cards/umbreon-pokemon-cards'], ['Full art cards', '/cards/full-art-pokemon-cards'], ['PSA 10 cards', '/cards/psa-10-pokemon-cards'], ['Card values', '/guides/pokemon-card-values']],
            '/japanese-pokemon-cards' => [['Japanese vs English', '/guides/japanese-pokemon-cards'], ['Booster boxes', '/booster-boxes'], ['Mega Evolution sets', '/sets/mega-evolution'], ['PokÃ©mon 151', '/sets/151'], ['30th Celebration', '/sets/30th-celebration']],
            '/english-pokemon-cards' => [['Perfect Order', '/sets/perfect-order'], ['Ascended Heroes', '/sets/ascended-heroes'], ['Prismatic Evolutions', '/sets/prismatic-evolutions'], ['Evolving Skies', '/sets/evolving-skies'], ['Every set', '/sets']],
            '/accessories' => [['Card sleeves', '/accessories/card-sleeves'], ['Toploaders and holders', '/accessories/toploaders'], ['Card binders', '/accessories/card-binders'], ['Card size guide', '/guides/pokemon-card-size']],
            '/premium-special-sets' => [['PokÃ©mon decks', '/pokemon-decks'], ['Elite Trainer Boxes', '/elite-trainer-boxes'], ['Booster boxes', '/booster-boxes']],
            '/pokemon-decks' => [['How to play', '/guides/how-to-play-pokemon-cards'], ['Premium and special sets', '/premium-special-sets'], ['Trainer cards', '/cards/trainer-pokemon-cards']],
            '/booster-box-cases' => [['Booster boxes', '/booster-boxes'], ['Bulk and wholesale', '/wholesale'], ['Shipping rates', '/shipping-returns']],
        ];
        $r = $map[$path] ?? [];
        if (!$r && str_starts_with($path, '/accessories/')) $r = $map['/accessories'];
    }
    return array_values(array_filter($r, fn($l) => $l[1] !== $path));
}
// table of contents for an article: gives each h2 an id and returns [body, [[id, text], ...]]
function article_toc(string $body): array {
    $toc = []; $used = [];
    $body = preg_replace_callback('#<h2>(.*?)</h2>#s', function ($m) use (&$toc, &$used) {
        $text = trim(html_entity_decode(strip_tags($m[1]), ENT_QUOTES)); $id = slugify($text) ?: 'section';
        while (isset($used[$id])) $id .= '-2';
        $used[$id] = 1; $toc[] = [$id, $text];
        return '<h2 id="' . h($id) . '">' . $m[1] . '</h2>';
    }, $body);
    return [$body, $toc];
}

/* ------------------------------------------------------------------ customer reviews */
function reviews_list(?int $productId = null, bool $featuredOnly = false, int $limit = 200): array {
    try {
        $w = ['r.published = 1']; $a = [];
        if ($productId !== null) { $w[] = 'r.product_id = ?'; $a[] = $productId; }
        if ($featuredOnly) $w[] = 'r.featured = 1';
        return all('SELECT r.*, p.title ptitle, p.handle FROM reviews r LEFT JOIN products p ON p.id = r.product_id WHERE ' . implode(' AND ', $w) . " ORDER BY r.review_date DESC, r.id DESC LIMIT $limit", $a);
    } catch (Throwable $e) { return []; }
}
function has_reviews(): bool { static $y = null; return $y ??= (bool)reviews_list(null, false, 1); }
function stars(int $n): string {
    return '<span class="stars" role="img" aria-label="' . $n . ' out of 5 stars">' . str_repeat('â˜…', $n) . '<span class="off">' . str_repeat('â˜…', 5 - $n) . '</span></span>';
}
function review_html(array $r, bool $showProduct = true): string {
    return '<figure class="review">' . stars((int)$r['rating'])
        . ($r['title'] ? '<strong class="review-title">' . h($r['title']) . '</strong>' : '')
        . '<blockquote>' . nl2br(h($r['body'])) . '</blockquote>'
        . ($r['photo'] ? '<a class="review-photo" href="/' . h($r['photo']) . '" target="_blank" rel="noopener"><img src="/' . h($r['photo']) . '" alt="Photo from ' . h($r['name']) . '" loading="lazy" width="320" height="240"></a>' : '')
        . '<figcaption><span>' . h($r['name']) . ($r['location'] ? ' Â· ' . h($r['location']) : '') . '</span><span class="mono small muted">' . h(date('M j, Y', strtotime($r['review_date']))) . '</span></figcaption>'
        . ($showProduct && !empty($r['handle']) ? '<a class="small" href="/products/' . h($r['handle']) . '">' . h(mb_strimwidth($r['ptitle'], 0, 60, 'â€¦')) . ' â†’</a>' : '')
        . '</figure>';
}
function page_reviews(): void {
    $rows = reviews_list();
    $avg = $rows ? round(array_sum(array_column($rows, 'rating')) / count($rows), 1) : 0;
    $meta = ['title' => setting('site_name') . ' reviews from customers', 'canonical' => '/reviews',
             'description' => 'Reviews of ' . setting('site_name') . ' from collectors, shops and resellers: how orders from Japan arrived, how they were packed and how we helped.',
             'robots' => $rows ? 'index,follow' : 'noindex,follow'];
    ob_start(); ?>
<div class="wrap">
  <nav class="crumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><span>Reviews</span></nav>
  <h1 class="h1">Customer reviews</h1>
  <?php if ($rows): ?>
    <p class="lead"><?= stars((int)round($avg)) ?> <strong class="mono"><?= $avg ?></strong> <span class="muted">out of 5 from <?= count($rows) ?> review<?= count($rows) === 1 ? '' : 's' ?></span></p>
    <div class="reviews-grid"><?php foreach ($rows as $r) echo review_html($r); ?></div>
  <?php else: ?>
    <p class="lead muted">Customer reviews will be posted here as they come in.</p>
  <?php endif ?>
  <p class="small muted">Every review comes from a real customer who ordered from us, sent by email, message or marketplace feedback, and is published with their permission.</p>
</div>
<?php
    echo view('layout', ['meta' => $meta, 'content' => ob_get_clean()]);
}

/* ------------------------------------------------------------------ product page */
function page_product(string $handle): void {
    $p = one('SELECT * FROM products WHERE handle = ? AND published = 1', [$handle]);
    if (!$p) not_found();
    $lad = ladder($p);
    $related = $p['set_url'] ? all('SELECT * FROM products WHERE set_url = ? AND id != ? AND published = 1 ORDER BY in_stock DESC, ' . str_replace('p.', '', SECTION_ORDER) . ', price_usd DESC LIMIT 8', [$p['set_url'], $p['id']]) : [];
    if (count($related) < 4) $related = array_merge($related, all('SELECT * FROM products WHERE section = ? AND game = ? AND id != ? AND published = 1 AND in_stock = 1 ORDER BY price_usd DESC LIMIT ' . (8 - count($related)), [$p['section'], $p['game'], $p['id']]));
    $set = $p['set_url'] ? one('SELECT * FROM collections WHERE path = ?', [$p['set_url']]) : null;
    $sec = one('SELECT * FROM collections WHERE path = ?', [$p['section_url']]);
    $crumbs = [['Home', '/']];
    if ($sec) $crumbs[] = [$sec['h1'] ?: $sec['title'], $sec['path']];
    elseif ($p['game_url'] && ($g = one('SELECT * FROM collections WHERE path = ?', [$p['game_url']]))) $crumbs[] = [$g['title'], $g['path']];
    $crumbs[] = [$p['title'], '/products/' . $p['handle']];
    $img = product_image($p);
    $abs = str_starts_with($img, 'http') ? $img : setting('site_url') . $img;
    $offer = ['@type' => 'Offer', 'url' => setting('site_url') . '/products/' . $p['handle'], 'priceCurrency' => 'USD',
              'availability' => $p['in_stock'] ? 'https://schema.org/InStock' : 'https://schema.org/OutOfStock', 'itemCondition' => 'https://schema.org/NewCondition',
              'seller' => ['@type' => 'Organization', 'name' => setting('site_name')]];
    if ($p['price_usd'] !== null) {
        $offer['price'] = number_format((float)$p['price_usd'], 2, '.', '');
        $offer['priceValidUntil'] = date('Y-m-d', strtotime('+30 days'));
        if (count($lad['tiers']) > 1) {
            $offer['priceSpecification'] = array_map(fn($t) => ['@type' => 'UnitPriceSpecification', 'price' => number_format($t[1], 2, '.', ''), 'priceCurrency' => 'USD',
                'eligibleQuantity' => ['@type' => 'QuantitativeValue', 'minValue' => $t[0], 'unitCode' => 'C62']], $lad['tiers']);
        }
        $offer['eligibleQuantity'] = ['@type' => 'QuantitativeValue', 'minValue' => $lad['moq'], 'unitCode' => 'C62'];
        $usShip = shipping_cost($lad['tiers'][0][1] * $lad['moq'], 'standard', 'United States', product_weight($p) * $lad['moq']);
        $offer['shippingDetails'] = ['@type' => 'OfferShippingDetails', 'shippingRate' => ['@type' => 'MonetaryAmount', 'value' => number_format($usShip, 2, '.', ''), 'currency' => 'USD'],
            'shippingDestination' => ['@type' => 'DefinedRegion', 'addressCountry' => 'US'],
            'deliveryTime' => ['@type' => 'ShippingDeliveryTime', 'handlingTime' => ['@type' => 'QuantitativeValue', 'minValue' => 0, 'maxValue' => 2, 'unitCode' => 'DAY'],
                               'transitTime' => ['@type' => 'QuantitativeValue', 'minValue' => 3, 'maxValue' => 6, 'unitCode' => 'DAY']]];
        $offer['hasMerchantReturnPolicy'] = return_policy_schema();
    }
    $schema = [breadcrumb_schema($crumbs), array_filter(['@context' => 'https://schema.org', '@type' => 'Product', 'name' => $p['title'], 'image' => $img ? [$abs] : null,
        'description' => trim(strip_tags($p['description'])) ?: $p['title'], 'sku' => $p['sku'] ?: $p['handle'], 'brand' => product_brand($p) ? ['@type' => 'Brand', 'name' => product_brand($p)] : null,
        'category' => $p['section'], 'offers' => $offer])];
    $reviews = reviews_list((int)$p['id']);
    if ($reviews) {
        $schema[1]['aggregateRating'] = ['@type' => 'AggregateRating', 'ratingValue' => round(array_sum(array_column($reviews, 'rating')) / count($reviews), 1), 'reviewCount' => count($reviews)];
        $schema[1]['review'] = array_map(fn($r) => ['@type' => 'Review', 'author' => ['@type' => 'Person', 'name' => $r['name']], 'datePublished' => $r['review_date'],
            'reviewRating' => ['@type' => 'Rating', 'ratingValue' => (int)$r['rating'], 'bestRating' => 5], 'reviewBody' => $r['body']], array_slice($reviews, 0, 5));
    }
    $desc = product_meta_desc($p);
    $meta = ['title' => product_seo_title($p), 'description' => $desc,
             'canonical' => '/products/' . $p['handle'], 'robots' => $p['seo_index'] ? 'index,follow' : 'noindex,follow', 'schema' => $schema, 'image' => $abs, 'og_type' => 'product'];
    echo view('layout', ['meta' => $meta, 'content' => view('product', compact('p', 'lad', 'related', 'set', 'crumbs', 'img', 'reviews') + ['explore' => product_explore($p)])]);
}

/* ------------------------------------------------------------------ cart, quick order, checkout, order */
function cart_payload(): array {
    $s = cart_summary();
    $lines = [];
    foreach ($s['lines'] as $l) $lines[] = ['id' => (int)$l['p']['id'], 'title' => $l['p']['title'], 'handle' => $l['p']['handle'], 'qty' => $l['qty'], 'step' => $l['ladder']['step'], 'moq' => $l['ladder']['moq'],
        'unit' => money($l['unit']), 'line' => money($l['line']), 'image' => product_image($l['p']),
        'next' => $l['next'] ? sprintf('Add %d more for %s each', $l['next'][0] - $l['qty'], money($l['next'][1])) : ''];
    return ['count' => $s['count'], 'items' => $s['items'], 'subtotal' => money($s['subtotal']), 'subtotal_usd' => $s['subtotal'], 'lines' => $lines,
            'min_ok' => $s['subtotal'] >= (float)setting('min_order_usd'), 'min' => money((float)setting('min_order_usd'))];
}
function api_cart(): void {
    if (is_post()) {
        csrf_check();
        $in = json_decode(file_get_contents('php://input'), true) ?: $_POST;
        $act = $in['action'] ?? 'add';
        $id = (int)($in['id'] ?? 0);
        $qty = (int)($in['qty'] ?? 0);
        if ($act === 'add') cart_set($id, (cart()[$id] ?? 0) + $qty);
        elseif ($act === 'set') cart_set($id, $qty);
        elseif ($act === 'remove') cart_set($id, 0);
        elseif ($act === 'clear') { start_session(); $_SESSION['cart'] = []; }
        elseif ($act === 'bulk') foreach ((array)($in['lines'] ?? []) as $l) cart_set((int)$l['id'], (cart()[(int)$l['id']] ?? 0) + (int)$l['qty']);
    }
    json_out(cart_payload());
}
function product_json(array $p): array {
    $lad = ladder($p);
    return ['id' => (int)$p['id'], 'title' => $p['title'], 'handle' => $p['handle'], 'sku' => $p['sku'], 'set' => $p['set_name'], 'number' => $p['card_number'], 'rarity' => $p['rarity'],
            'lang' => $p['language'], 'in_stock' => (bool)$p['in_stock'], 'moq' => $lad['moq'], 'step' => $lad['step'], 'price' => money(unit_price($lad, $lad['moq'])),
            'best' => count($lad['tiers']) > 1 ? money(end($lad['tiers'])[1]) . ' at ' . end($lad['tiers'])[0] . '+' : '', 'image' => product_image($p)];
}
function api_search(): void {
    $s = trim((string)($_GET['q'] ?? ''));
    if (mb_strlen($s) < 2) json_out([]);
    [$from, $args] = listing_query(null, $s, ['stock' => !empty($_GET['stock'])]);
    $rows = all("SELECT p.* $from ORDER BY p.in_stock DESC, " . SECTION_ORDER . ", p.seo_index DESC, p.price_usd DESC LIMIT 12", $args);
    json_out(array_map('product_json', $rows));
}
function api_quick(): void {
    // paste list: one line per item, "<sku or name>, <qty>" or "<qty> x <name>"
    if (!is_post()) json_out(['error' => 'POST'], 405);
    csrf_check();
    $text = (string)($_POST['lines'] ?? '');
    $out = [];
    foreach (preg_split('/\r?\n/', $text) as $line) {
        $line = trim($line);
        if ($line === '') continue;
        $qty = 1; $term = $line;
        if (preg_match('/^(.*?)[,;\t]\s*(\d+)\s*$/', $line, $m)) { $term = $m[1]; $qty = (int)$m[2]; }
        elseif (preg_match('/^(\d+)\s*[xÃ—]\s*(.+)$/iu', $line, $m)) { $qty = (int)$m[1]; $term = $m[2]; }
        $term = trim($term);
        $p = one('SELECT * FROM products WHERE published = 1 AND (sku = ? COLLATE NOCASE OR handle = ?) LIMIT 1', [$term, slugify($term)]);
        if (!$p) { [$from, $args] = listing_query(null, $term, []); $p = one("SELECT p.* $from ORDER BY p.in_stock DESC, " . SECTION_ORDER . ' LIMIT 1', $args); }
        $out[] = ['line' => $line, 'qty' => $qty, 'match' => $p ? product_json($p) : null];
    }
    json_out($out);
}
function page_quick(): void {
    $meta = ['title' => 'Quick order | ' . setting('site_name'), 'robots' => 'noindex,follow', 'canonical' => '/quick-order'];
    echo view('layout', ['meta' => $meta, 'content' => view('quick')]);
}
function page_cart(): void {
    $s = cart_summary();
    $meta = ['title' => 'Your order | ' . setting('site_name'), 'robots' => 'noindex,nofollow'];
    echo view('layout', ['meta' => $meta, 'content' => view('cart', ['s' => $s])]);
}
// Bitcoin price in USD for the order page (two public sources; null if both are unreachable)
function btc_usd(): ?float {
    $j = json_decode((string)http_get('https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd', 5), true);
    if (!empty($j['bitcoin']['usd'])) return (float)$j['bitcoin']['usd'];
    $j = json_decode((string)http_get('https://api.coinbase.com/v2/prices/BTC-USD/spot', 5), true);
    return !empty($j['data']['amount']) ? (float)$j['data']['amount'] : null;
}
const COUNTRIES = ['United States', 'Canada', 'United Kingdom', 'Japan', 'Australia', 'New Zealand', 'Germany', 'France', 'Netherlands', 'Belgium', 'Spain', 'Italy', 'Sweden', 'Norway', 'Denmark', 'Finland', 'Ireland', 'Switzerland', 'Austria', 'Poland', 'Portugal', 'Czech Republic', 'Greece', 'Singapore', 'Hong Kong', 'Taiwan', 'South Korea', 'Malaysia', 'Philippines', 'Thailand', 'Indonesia', 'Vietnam', 'United Arab Emirates', 'Saudi Arabia', 'Mexico', 'Brazil', 'Chile', 'South Africa', 'Nigeria', 'Cameroon', 'Other'];
function page_checkout(): void {
    $s = cart_summary();
    if (!$s['lines']) redirect('/cart');
    $errors = []; $d = $_POST;
    if (is_post()) {
        csrf_check();
        foreach (['name' => 'Name', 'email' => 'Email', 'country' => 'Country', 'address1' => 'Address', 'city' => 'City'] as $k => $label) if (trim((string)($d[$k] ?? '')) === '') $errors[$k] = "$label is required.";
        if (!empty($d['email']) && !filter_var($d['email'], FILTER_VALIDATE_EMAIL)) $errors['email'] = 'Enter a valid email.';
        $method = ($d['shipping'] ?? '') === 'express' ? 'express' : 'standard';
        $pay = isset(PAYMENT_METHODS[$d['payment'] ?? '']) ? $d['payment'] : 'bitcoin';
        $only = PAYMENT_METHODS[$pay][2];
        if ($only && ($d['country'] ?? '') !== $only) $errors['payment'] = PAYMENT_METHODS[$pay][0] . ' is only for ' . ($only === 'United States' ? 'US' : 'UK') . ' customers. Choose another payment method.';
        if (!empty($d['country']) && !in_array($d['country'], COUNTRIES, true)) $errors['country'] = 'Choose your country from the list.';
        $kg = cart_weight($s['lines']);
        $ship = shipping_cost($s['subtotal'], $method, (string)($d['country'] ?? 'United States'), $kg);
        $total = $s['subtotal'] + $ship;
        if ($total < (float)setting('min_order_usd')) $errors['min'] = 'The minimum order is ' . money((float)setting('min_order_usd')) . ' including shipping.';
        if (!$errors) {
            $code = 'TM-' . strtoupper(substr(bin2hex(random_bytes(4)), 0, 6));
            $token = bin2hex(random_bytes(12));
            db()->beginTransaction();
            q('INSERT INTO orders(code, token, name, company, email, phone, country, address1, address2, city, region, postcode, shipping_method, payment_method, currency, rate, subtotal_usd, shipping_usd, total_usd, notes, hold_until)
               VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)', [$code, $token, trim($d['name']), trim($d['company'] ?? ''), trim($d['email']), trim($d['phone'] ?? ''), $d['country'], trim($d['address1']),
               trim($d['address2'] ?? ''), trim($d['city']), trim($d['region'] ?? ''), trim($d['postcode'] ?? ''), $method, $pay, currency(), rates()[currency()] ?? 1, $s['subtotal'], $ship, $total,
               trim($d['notes'] ?? ''), date('Y-m-d H:i:s', time() + 3600 * (int)setting('hold_hours'))]);
            $oid = (int)db()->lastInsertId();
            q('UPDATE orders SET weight_kg = ? WHERE id = ?', [$kg, $oid]);
            if ($pay === 'bitcoin' && ($btcUsd = btc_usd())) q('UPDATE orders SET btc_rate = ?, btc_amount = ? WHERE id = ?', [$btcUsd, number_format($total / $btcUsd, 8, '.', ''), $oid]);
            foreach ($s['lines'] as $l) q('INSERT INTO order_items(order_id, product_id, title, sku, handle, qty, unit_usd, line_usd) VALUES(?,?,?,?,?,?,?,?)', [$oid, $l['p']['id'], $l['p']['title'], $l['p']['sku'], $l['p']['handle'], $l['qty'], $l['unit'], $l['line']]);
            db()->commit();
            $_SESSION['cart'] = [];
            $_SESSION['orders'][] = $code;
            $o = one('SELECT * FROM orders WHERE id = ?', [$oid]);
            $link = setting('site_url') . "/order/$code?k=$token";
            $txt = view('email_order', ['o' => $o, 'items' => all('SELECT * FROM order_items WHERE order_id = ?', [$oid]), 'link' => $link]);
            send_mail($o['email'], "Order $code received â€“ " . setting('site_name'), $txt);
            send_mail(setting('orders_email'), "New order $code (" . money($total, 'USD') . ")", $txt);
            redirect("/order/$code?k=$token");
        }
    }
    $meta = ['title' => 'Checkout | ' . setting('site_name'), 'robots' => 'noindex,nofollow'];
    echo view('layout', ['meta' => $meta, 'content' => view('checkout', compact('s', 'errors', 'd'))]);
}
function page_order(string $code): void {
    start_session();
    $o = one('SELECT * FROM orders WHERE code = ?', [$code]);
    if (!$o || (!hash_equals($o['token'], (string)($_GET['k'] ?? '')) && !in_array($code, $_SESSION['orders'] ?? [], true))) not_found();
    $items = all('SELECT * FROM order_items WHERE order_id = ?', [$o['id']]);
    $meta = ['title' => "Order {$o['code']} | " . setting('site_name'), 'robots' => 'noindex,nofollow'];
    echo view('layout', ['meta' => $meta, 'content' => view('order', compact('o', 'items'))]);
}

/* ------------------------------------------------------------------ robots & sitemaps */
function page_robots(): void {
    header('Content-Type: text/plain; charset=utf-8');
    echo "User-agent: *\nDisallow: /admin\nDisallow: /cart\nDisallow: /checkout\nDisallow: /order/\nDisallow: /api/\nDisallow: /currency/\nDisallow: /search\nDisallow: /quick-order\nDisallow: /*?*sort=\nDisallow: /*?*view=\n\nSitemap: " . setting('site_url') . "/sitemap.xml\n";
}
const SITEMAP_SIZE = 5000;
function page_sitemap_index(): void {
    header('Content-Type: application/xml; charset=utf-8');
    $n = (int)val('SELECT COUNT(*) FROM products WHERE published = 1 AND seo_index = 1');
    $base = setting('site_url');
    echo '<?xml version="1.0" encoding="UTF-8"?>' . "\n<sitemapindex xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n<sitemap><loc>$base/sitemap-pages-1.xml</loc></sitemap>\n";
    for ($i = 1; $i <= max(1, (int)ceil($n / SITEMAP_SIZE)); $i++) echo "<sitemap><loc>$base/sitemap-products-$i.xml</loc></sitemap>\n";
    echo '</sitemapindex>';
}
function page_sitemap(string $type, int $n): void {
    header('Content-Type: application/xml; charset=utf-8');
    $base = setting('site_url');
    echo '<?xml version="1.0" encoding="UTF-8"?>' . "\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\" xmlns:image=\"http://www.google.com/schemas/sitemap-image/1.1\">\n";
    if ($type === 'pages') {
        echo "<url><loc>$base/</loc></url>\n<url><loc>$base/sets</loc></url>\n<url><loc>$base/guides</loc></url>\n<url><loc>$base/blog</loc></url>\n";
        foreach (all("SELECT c.path, c.updated_at FROM collections c WHERE c.seo_index = 1 AND EXISTS (SELECT 1 FROM product_paths pp WHERE pp.path = c.path)") as $r) echo '<url><loc>' . h($base . $r['path']) . '</loc><lastmod>' . substr($r['updated_at'], 0, 10) . "</lastmod></url>\n";
        foreach (all('SELECT path, updated_at FROM pages WHERE published = 1 AND seo_index = 1') as $r) echo '<url><loc>' . h($base . $r['path']) . '</loc><lastmod>' . substr($r['updated_at'], 0, 10) . "</lastmod></url>\n";
        if (has_reviews()) echo '<url><loc>' . h($base . '/reviews') . "</loc></url>\n";
    } else {
        $off = ($n - 1) * SITEMAP_SIZE;
        foreach (all('SELECT handle, title, updated_at, image_url, image_local, alt_text FROM products WHERE published = 1 AND seo_index = 1 ORDER BY id LIMIT ' . SITEMAP_SIZE . " OFFSET $off") as $r) {
            $img = product_image($r);
            if ($img && !str_starts_with($img, 'http')) $img = $base . $img;
            echo '<url><loc>' . h("$base/products/{$r['handle']}") . '</loc><lastmod>' . substr($r['updated_at'], 0, 10) . '</lastmod>'
                . ($img ? '<image:image><image:loc>' . h($img) . '</image:loc></image:image>' : '') . "</url>\n";
        }
    }
    echo '</urlset>';
}

/* ------------------------------------------------------------------ Google Merchant Center product feed */
function page_google_feed(): void {
    header('Content-Type: application/xml; charset=utf-8');
    $base = setting('site_url');
    echo '<?xml version="1.0" encoding="UTF-8"?>' . "\n" . '<rss version="2.0" xmlns:g="http://base.google.com/ns/1.0"><channel>'
        . '<title>' . h(setting('site_name')) . '</title><link>' . h($base) . '</link><description>' . h(setting('tagline')) . "</description>\n";
    $st = q("SELECT * FROM products WHERE published = 1 AND seo_index = 1 AND price_usd IS NOT NULL AND (image_url != '' OR image_local NOT IN ('', '!')) ORDER BY id");
    while ($p = $st->fetch()) {
        $img = product_image($p);
        if ($img && !str_starts_with($img, 'http')) $img = $base . $img;
        $lad = ladder($p);
        $desc = trim(preg_replace('/\s+/', ' ', strip_tags($p['description']))) ?: $p['title'];
        $type = $p['game'] . ' > ' . $p['section'] . ($p['set_name'] ? ' > ' . $p['set_name'] : '');
        echo '<item><g:id>' . (int)$p['id'] . '</g:id><g:title>' . h(mb_substr($p['title'], 0, 150)) . '</g:title><g:description>' . h(mb_substr($desc, 0, 4900)) . '</g:description>'
            . '<g:link>' . h("$base/products/{$p['handle']}") . '</g:link><g:image_link>' . h($img) . '</g:image_link>'
            . '<g:availability>' . ($p['in_stock'] ? 'in_stock' : 'out_of_stock') . '</g:availability><g:price>' . number_format((float)$lad['tiers'][0][1], 2, '.', '') . ' USD</g:price>'
            . '<g:condition>new</g:condition><g:brand>' . h($p['game'] === 'Accessories' ? setting('site_name') : $p['game']) . '</g:brand><g:identifier_exists>no</g:identifier_exists>'
            . '<g:google_product_category>Toys &amp; Games &gt; Games &gt; Card Games</g:google_product_category><g:product_type>' . h($type) . '</g:product_type>'
            . ($lad['moq'] > 1 ? '<g:custom_label_0>MOQ ' . $lad['moq'] . '</g:custom_label_0>' : '')
            . '<g:custom_label_1>' . h($p['language']) . "</g:custom_label_1></item>\n";
    }
    echo '</channel></rss>';
}

