function admin_images_batch(): void {
    if (!is_post()) json_out(['error' => 'POST'], 405);
    @set_time_limit(120);
    $dir = ROOT . '/uploads/products';
    if (!is_dir($dir)) mkdir($dir, 0775, true);
    $rows = all("SELECT id, handle, image_url FROM products WHERE image_local = '' AND image_url != '' ORDER BY seo_index DESC, in_stock DESC, id LIMIT 25");
    $done = 0; $failed = 0;
    foreach ($rows as $r) {
        $ctx = stream_context_create(['http' => ['timeout' => 15, 'header' => "User-Agent: Toramori image copier\r\n"]]);
        $data = @file_get_contents($r['image_url'], false, $ctx);
        $info = $data ? @getimagesizefromstring($data) : false;
        $ext = ['image/jpeg' => 'jpg', 'image/png' => 'png', 'image/webp' => 'webp', 'image/gif' => 'gif'][$info['mime'] ?? ''] ?? null;
        if ($ext) {
            $file = substr($r['handle'], 0, 120) . '.' . $ext;
            file_put_contents("$dir/$file", $data);
            q('UPDATE products SET image_local = ? WHERE id = ?', ["uploads/products/$file", $r['id']]);
            $done++;
        } else {
            q("UPDATE products SET image_local = '!' WHERE id = ?", [$r['id']]); // could not copy: keep loading it from the original address
            $failed++;
        }
    }
    json_out(['done' => $done, 'failed' => $failed, 'remaining' => (int)val("SELECT COUNT(*) FROM products WHERE image_local = '' AND image_url != ''")]);
}
function admin_backup(): never {
    db()->exec('PRAGMA wal_checkpoint(FULL)');
    header('Content-Type: application/octet-stream');
    header('Content-Disposition: attachment; filename="toramori-backup-' . date('Y-m-d-His') . '.sqlite"');
    readfile(function_exists('db_file') ? db_file() : DATA . '/toramori.sqlite');
    exit;
}

/* ------------------------------------------------------------------ entry point */
/* ------------------------------------------------------------------ reviews */
function review_photo_upload(): ?string {
    if (empty($_FILES['photo']) || $_FILES['photo']['error'] === UPLOAD_ERR_NO_FILE) return null;
    $f = $_FILES['photo'];
    if ($f['error'] !== UPLOAD_ERR_OK || $f['size'] > 8 * 1024 * 1024) { flash('The photo was not saved: use a JPG, PNG or WebP under 8 MB.'); return null; }
    $info = @getimagesize($f['tmp_name']);
    $ext = ['image/jpeg' => 'jpg', 'image/png' => 'png', 'image/webp' => 'webp'][$info['mime'] ?? ''] ?? null;
    if (!$ext) { flash('The photo was not saved: use a JPG, PNG or WebP image.'); return null; }
    $dir = ROOT . '/uploads/reviews';
    if (!is_dir($dir)) mkdir($dir, 0775, true);
    $name = 'review-' . date('Ymd') . '-' . bin2hex(random_bytes(4)) . '.' . $ext;
    move_uploaded_file($f['tmp_name'], "$dir/$name");
    return "uploads/reviews/$name";
}
function admin_reviews(): void {
    if (is_post()) {
        $id = (int)($_POST['id'] ?? 0); $do = (string)($_POST['do'] ?? '');
        if ($do === 'delete') { $r = one('SELECT photo FROM reviews WHERE id = ?', [$id]); if ($r && $r['photo']) @unlink(ROOT . '/' . $r['photo']); q('DELETE FROM reviews WHERE id = ?', [$id]); flash('Review deleted.'); }
        if ($do === 'toggle') { q('UPDATE reviews SET published = 1 - published WHERE id = ?', [$id]); flash('Review updated.'); }
        if ($do === 'feature') { q('UPDATE reviews SET featured = 1 - featured WHERE id = ?', [$id]); flash('Review updated.'); }
        redirect('/admin/reviews');
    }
    $rows = all('SELECT r.*, p.title ptitle, p.handle FROM reviews r LEFT JOIN products p ON p.id = r.product_id ORDER BY r.review_date DESC, r.id DESC');
    $avg = $rows ? round(array_sum(array_column(array_filter($rows, fn($r) => $r['published']), 'rating')) / max(1, count(array_filter($rows, fn($r) => $r['published']))), 1) : 0;
    ob_start(); ?>
<div class="row-between"><h1>Reviews</h1><a class="btn primary" href="/admin/reviews/edit">+ Add a review</a></div>
<p class="muted">Customer reviews show on the homepage, on a <a href="/reviews" target="_blank">reviews page</a>, and on the product they are about. <?= $rows ? count($rows) . ' review' . (count($rows) === 1 ? '' : 's') . ' Â· average ' . $avg . ' / 5' : '' ?></p>
<p class="note small">Only add real reviews from real customers, in their own words (from email, WhatsApp, eBay, Instagram and so on). Writing reviews yourself or paying for them is illegal in the US under the FTC's rule on fake reviews, and Google removes sites that use them.</p>
<?php if (!$rows): ?><section class="card"><p>No reviews yet. Press <strong>Add a review</strong> to add your first one: copy what the customer wrote, add their first name and city, and upload a photo they sent if you have one.</p></section>
<?php else: ?>
<div class="table-wrap card"><table class="tbl"><thead><tr><th>Photo</th><th>Customer</th><th>Rating</th><th>Review</th><th>Product</th><th>Date</th><th>Shown</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr>
  <td><?php if ($r['photo']): ?><img src="/<?= h($r['photo']) ?>" alt="" width="48" height="48" style="object-fit:cover;border-radius:4px"><?php endif ?></td>
  <td><strong><?= h($r['name']) ?></strong><br><span class="muted small"><?= h($r['location']) ?><?= $r['source'] ? ' Â· ' . h($r['source']) : '' ?></span></td>
  <td class="mono"><?= str_repeat('â˜…', (int)$r['rating']) ?></td>
  <td class="small"><?= $r['title'] ? '<strong>' . h($r['title']) . '</strong><br>' : '' ?><?= h(mb_strimwidth($r['body'], 0, 140, 'â€¦')) ?></td>
  <td class="small"><?= $r['ptitle'] ? '<a href="/products/' . h($r['handle']) . '" target="_blank">' . h(mb_strimwidth($r['ptitle'], 0, 40, 'â€¦')) . '</a>' : '<span class="muted">Shop review</span>' ?></td>
  <td class="mono small"><?= h($r['review_date']) ?></td>
  <td class="small"><?= $r['published'] ? 'Yes' : '<span class="muted">Hidden</span>' ?><?= $r['featured'] ? '<br><span class="pill">Homepage</span>' : '' ?></td>
  <td><div class="btns"><a class="btn small" href="/admin/reviews/edit?id=<?= (int)$r['id'] ?>">Edit</a>
    <form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn small" name="do" value="toggle"><?= $r['published'] ? 'Hide' : 'Show' ?></button></form>
    <form method="post" data-confirm="Delete this review?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn small danger" name="do" value="delete">Delete</button></form></div></td>
</tr><?php endforeach ?></tbody></table></div>
<?php endif;
    echo admin_shell('Reviews', ob_get_clean(), 'reviews');
}
function admin_review_edit(): void {
    $id = (int)($_GET['id'] ?? 0);
    $r = $id ? one('SELECT * FROM reviews WHERE id = ?', [$id]) : null;
    if ($id && !$r) redirect('/admin/reviews');
    $r = $r ?: ['name' => '', 'location' => '', 'rating' => 5, 'title' => '', 'body' => '', 'product_id' => null, 'photo' => '', 'source' => '', 'review_date' => date('Y-m-d'), 'published' => 1, 'featured' => 1];
    $err = '';
    if (is_post()) {
        $d = $_POST;
        $pid = null;
        if (trim((string)($d['product'] ?? '')) !== '') {
            $ref = trim((string)$d['product']);
            if (preg_match('#/products/([a-z0-9-]+)#', $ref, $m)) $ref = $m[1];
            $pid = (int)(val('SELECT id FROM products WHERE handle = ?', [slugify($ref)]) ?? 0) ?: null;
            if (!$pid) $err = 'No product found for "' . $ref . '". Paste the product page address, or leave it empty for a shop review.';
        }
        if (trim((string)$d['name']) === '' || trim((string)$d['body']) === '') $err = 'Add the customer name and what they wrote.';
        if (!$err) {
            $photo = review_photo_upload();
            if (!empty($d['remove_photo']) && $r['photo']) { @unlink(ROOT . '/' . $r['photo']); $r['photo'] = ''; }
            $vals = ['name' => mb_substr(trim((string)$d['name']), 0, 80), 'location' => mb_substr(trim((string)$d['location']), 0, 80), 'rating' => max(1, min(5, (int)$d['rating'])),
                     'title' => mb_substr(trim((string)$d['title']), 0, 120), 'body' => mb_substr(trim((string)$d['body']), 0, 3000), 'product_id' => $pid,
                     'photo' => $photo ?? $r['photo'], 'source' => mb_substr(trim((string)$d['source']), 0, 60),
                     'review_date' => preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)$d['review_date']) ? $d['review_date'] : date('Y-m-d'),
                     'published' => isset($d['published']) ? 1 : 0, 'featured' => isset($d['featured']) ? 1 : 0];
            if ($id) q('UPDATE reviews SET ' . implode(', ', array_map(fn($k) => "$k = ?", array_keys($vals))) . ' WHERE id = ?', [...array_values($vals), $id]);
            else q('INSERT INTO reviews(' . implode(',', array_keys($vals)) . ') VALUES(' . implode(',', array_fill(0, count($vals), '?')) . ')', array_values($vals));
            flash('Review saved.');
            redirect('/admin/reviews');
        }
        $r = array_merge($r, $d);
    }
    $prod = $r['product_id'] ? one('SELECT handle, title FROM products WHERE id = ?', [$r['product_id']]) : null;
    ob_start(); ?>
<p><a href="/admin/reviews">â† All reviews</a></p>
<h1><?= $id ? 'Edit review' : 'Add a review' ?></h1>
<?php if ($err): ?><p class="alert"><?= h($err) ?></p><?php endif ?>
<form method="post" enctype="multipart/form-data" class="card narrow-form"><?= csrf_field() ?>
  <div class="row3">
    <label>Customer name <span class="muted">(first name and initial is fine)</span><input name="name" required maxlength="80" value="<?= h($r['name']) ?>" placeholder="Jason M."></label>
    <label>City, state or country <span class="muted">optional</span><input name="location" maxlength="80" value="<?= h($r['location']) ?>" placeholder="Austin, TX"></label>
    <label>Rating<select name="rating"><?php for ($i = 5; $i >= 1; $i--): ?><option value="<?= $i ?>" <?= (int)$r['rating'] === $i ? 'selected' : '' ?>><?= str_repeat('â˜…', $i) . str_repeat('â˜†', 5 - $i) ?> (<?= $i ?>)</option><?php endfor ?></select></label>
  </div>
  <label>Headline <span class="muted">optional</span><input name="title" maxlength="120" value="<?= h($r['title']) ?>" placeholder="Fast shipping to Texas"></label>
  <label>What the customer wrote<textarea name="body" rows="6" required maxlength="3000"><?= h($r['body']) ?></textarea></label>
  <div class="row3">
    <label>Where it came from <span class="muted">optional</span><input name="source" maxlength="60" value="<?= h($r['source']) ?>" placeholder="Email, WhatsApp, eBayâ€¦"></label>
    <label>Date of the review<input type="date" name="review_date" value="<?= h($r['review_date']) ?>"></label>
    <label>About a product? <span class="muted">paste its page address, or leave empty</span><input name="product" value="<?= h($prod ? '/products/' . $prod['handle'] : (string)($_POST['product'] ?? '')) ?>" placeholder="/products/storm-emeralda-m6-booster-box"></label>
  </div>
  <?php if ($prod): ?><p class="small muted">Shows on: <a href="/products/<?= h($prod['handle']) ?>" target="_blank"><?= h($prod['title']) ?></a></p><?php endif ?>
  <label>Photo from the customer <span class="muted">optional Â· JPG, PNG or WebP, up to 8 MB</span><input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label>
  <?php if ($r['photo']): ?><p><img src="/<?= h($r['photo']) ?>" alt="" style="max-width:220px;border-radius:6px"><br><label class="inline small"><input type="checkbox" name="remove_photo" value="1"> Remove this photo</label></p><?php endif ?>
  <div class="checks"><label class="inline"><input type="checkbox" name="published" <?= $r['published'] ? 'checked' : '' ?>> Show on the site</label><label class="inline"><input type="checkbox" name="featured" <?= $r['featured'] ? 'checked' : '' ?>> Show on the homepage</label></div>
  <p class="note small">Only add reviews customers really wrote. Keep their words; you can fix obvious typos.</p>
  <button class="btn primary">Save review</button>
</form>
<?php echo admin_shell($id ? 'Edit review' : 'Add a review', ob_get_clean(), 'reviews');
}

function admin_main(string $path): void {
    start_session();
    $apath = '/' . trim(substr($path, strlen('/admin')), '/');

    /* ------------------------------------------------------------------ auth */
    // No password yet, or the owner asked for a new one by putting an empty reset-admin.txt next to index.php
    // (only someone with access to the hosting can do that).
    $reset = is_file(ROOT . '/reset-admin.txt');
    if (setting('admin_password_hash') === '' || $reset) {
        $err = '';
        if (is_post()) {
            csrf_check();
            $pw = (string)($_POST['password'] ?? '');
            if (mb_strlen($pw) < 10) $err = 'Use at least 10 characters.';
            elseif ($pw !== ($_POST['password2'] ?? '')) $err = 'The two passwords do not match.';
            elseif ($reset && !@unlink(ROOT . '/reset-admin.txt')) $err = 'reset-admin.txt could not be removed. Delete it in your hosting file manager, then set the password here.';
            else { set_setting('admin_password_hash', password_hash($pw, PASSWORD_DEFAULT)); set_setting('login_fails', '[]'); session_regenerate_id(true); $_SESSION['admin'] = 1; $_SESSION['admin_ip'] = $_SERVER['REMOTE_ADDR'] ?? ''; redirect('/admin'); }
        }
        echo admin_shell($reset ? 'Set a new admin password' : 'Create your admin password', '<form method="post" class="card narrow">' . csrf_field() . '<h1>' . ($reset ? 'Set a new admin password' : 'Welcome to your Toramori admin') . '</h1><p class="muted">' . ($reset ? 'reset-admin.txt was found, so you can choose a new password. The file is removed once you save.' : 'Create the password you will use to sign in. Keep it somewhere safe.') . ' Your username is <strong>' . h(setting('admin_user')) . '</strong>.</p>'
            . ($err ? '<p class="alert">' . h($err) . '</p>' : '') . '<label>Password<input type="password" name="password" required minlength="10" autocomplete="new-password"></label><label>Repeat password<input type="password" name="password2" required autocomplete="new-password"></label><button class="btn primary">Create password</button></form>', '', false);
        exit;
    }
    if ($apath === '/logout') { $_SESSION = []; session_destroy(); redirect('/admin'); }
    if (!admin_ok()) {
        $err = '';
        $ip = $_SERVER['REMOTE_ADDR'] ?? '';
        $fails = json_decode(setting('login_fails'), true) ?: [];
        foreach ($fails as $k => $f) if ($f[1] < time() - 900) unset($fails[$k]);   // forget failures older than 15 minutes
        $locked = ($fails[$ip][0] ?? 0) >= 8;
        if (is_post()) {
            csrf_check();
            if ($locked) $err = 'Too many wrong attempts. Wait 15 minutes and try again.';
            else {
                $userOk = hash_equals(mb_strtolower(setting('admin_user')), mb_strtolower(trim((string)($_POST['user'] ?? ''))));
                if (password_verify((string)($_POST['password'] ?? ''), setting('admin_password_hash')) && $userOk) {
                    unset($fails[$ip]); set_setting('login_fails', json_encode($fails));
                    session_regenerate_id(true); $_SESSION['admin'] = 1; $_SESSION['admin_ip'] = $ip;
                    redirect('/admin' . ($apath !== '/' ? $apath : ''));
                }
                $fails[$ip] = [($fails[$ip][0] ?? 0) + 1, time()];
                set_setting('login_fails', json_encode($fails));
                usleep(700000);
                $err = 'That username or password is not right.';
            }
        }
        echo admin_shell('Sign in', '<form method="post" class="card narrow">' . csrf_field() . '<h1>Sign in</h1>' . ($err ? '<p class="alert">' . h($err) . '</p>' : '')
            . '<label>Username<input name="user" required autofocus autocomplete="username" value="' . h((string)($_POST['user'] ?? '')) . '"></label>'
            . '<label>Password<input type="password" name="password" required autocomplete="current-password"></label><button class="btn primary">Sign in</button>'
            . '<p class="small muted">Forgot the password? In your hosting file manager, create an empty file named reset-admin.txt next to index.php, then reload this page.</p></form>', '', false);
        exit;
    }
    if (is_post()) csrf_check();

    /* ------------------------------------------------------------------ routes */
    switch (true) {
        case $apath === '/': admin_dashboard(); break;
        case $apath === '/products': admin_products(); break;
        case $apath === '/products/edit': admin_product_edit(); break;
        case $apath === '/products/bulk': admin_products_bulk(); break;
        case $apath === '/import': admin_import(); break;
        case $apath === '/export': admin_export(); break;
        case $apath === '/orders': admin_orders(); break;
        case $apath === '/orders/view': admin_order_view(); break;
        case $apath === '/reviews': admin_reviews(); break;
        case $apath === '/reviews/edit': admin_review_edit(); break;
        case $apath === '/pages': admin_pages(); break;
        case $apath === '/pages/edit': admin_page_edit(); break;
        case $apath === '/collections/edit': admin_collection_edit(); break;
        case $apath === '/seo': admin_seo(); break;
        case $apath === '/redirects': admin_redirects(); break;
        case $apath === '/settings': admin_settings(); break;
        case $apath === '/tools': admin_tools(); break;
        case $apath === '/tools/images': admin_images_batch(); break;
        case $apath === '/tools/backup': admin_backup(); break;
        case $apath === '/upload': admin_upload(); break;
        default: http_response_code(404); echo admin_shell('Not found', '<div class="card"><h1>Not found</h1></div>', '');
    }


}

